from fastapi import FastAPI, Form, HTTPException
from fastapi.testclient import TestClient
from typing import Optional

app = FastAPI()

@app.post("/test")
async def test_endpoint(val: Optional[int] = Form(None)):
    return {"val": val}

client = TestClient(app)

def test_empty_string_form_value():
    # If val is sent as empty string, it should be treated as missing and use default None
    # But based on the bug report, it might be sent as "" to validation and fail
    response = client.post("/test", data={"val": ""})
    assert response.status_code == 200
    assert response.json() == {"val": None}

if __name__ == "__main__":
    try:
        test_empty_string_form_value()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
